using RailwayWebBuilderCore.Enums;

namespace RailwayWebBuilderCore._SiteData.ModelRailways.Layouts;

internal class GrangeLane : LayoutBase
{
    public GrangeLane()
    {
        Name = LayoutNamesEnums.GrangeLane;
        Description = "Grange Lane's concept started with the purchase of a particular locomotive, a Dapol 08. Having previously built small and micro layouts, the challenge was to see what could be fitted into a compact O gauge layout - main line trains being out of the question, the answer was a small yard on the edge of an industrial area, served by trip freights from a nearby marshalling yard. The track plan is based on the well documented Inglenook principle, with the addition of a station platform and run-round loop for operational interest. The scene is a yard in the 1970s nearing the end of its useful life, the weeds taking over but traffic still handled for the large engineering works that forms the backdrop, while the semi-disused station platform still handles a small amount of consignments from nearby industry and the remains of a passenger service - though this too is shortly to disappear and the former through route will close. Trackwork is hand built from C&L components apart from the Peco double-slip in the centre, which is a great space saver, and the large factory complex along the rear is made from Skytrex components. Most of the small goods stock is Parkside and Slaters kits, heavily weathered to suit their role - some even have real rust.";
    }
}
